$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot '../glass.ps1') -PrepareOnly
function A($x,$m){if(-not $x){throw $m}}
try { Initialize-CardSlots; $old=Copy-CardSlots; $script:cfg.freePlacement=$false; $last=Get-CardPlacementLastRow; A (Set-CardSlot cpu ($last+1) 0) 'default frontier rejected'; A (-not (Set-CardSlot cpu ($last+2) 0)) 'default beyond accepted';$script:cfg.freePlacement=$true;A (Set-CardSlot cpu 11 0) 'free row';$script:cfg.freePlacement=$false;A (-not (Set-CardSlot cpu 11 0)) 'policy';Invoke-CardAutoArrange HostPriority $false|Out-Null; foreach($cell in $cards){$p=$script:cfg.cardSlots[$cell.key];$span=if((Get-CardShape $cell.key)-eq 'long'){2}else{1};if($cell.side -eq 'R'){A ($p.column -ge 2 -and $p.column+$span -le 4) 'remote escaped right lane'}else{A ($p.column -ge 0 -and $p.column+$span -le 2) 'local escaped left lane'}}; $seen=@{};foreach($p in Get-CardPacking $script:cardOrder 4){$span=$p.span;for($c=$p.column;$c -lt $p.column+$span;$c++){A (-not $seen.ContainsKey("$($p.row):$c")) 'overlap';$seen["$($p.row):$c"]=$p.key}};Invoke-CardAutoArrange HardwarePriority $false|Out-Null;'PASS: placement frontier, free mode, auto arrange, nonoverlap'}finally{$script:exiting=$true;$window.Close();if($script:tray){$script:tray.Dispose()};if($menu){$menu.Dispose()};if($script:trayFont){$script:trayFont.Dispose()};if($script:trayBitmap){$script:trayBitmap.Dispose()}}